<script setup lang="ts">
import { Settings2,FolderOpen,ScrollText,Clock3,LogOut,ArrowUpRight,PanelLeftClose } from 'lucide-vue-next'
import { api,session } from '../app/api'
import { ref } from 'vue'
defineProps<{page:string;model:string;ready:boolean}>()
const emit=defineEmits<{navigate:[page:string]}>();const collapsed=ref(false),error=ref('')
async function logout(){try{await api('/auth/logout','POST',{});session.value=null}catch(e){error.value=(e as Error).message}}
</script>
<template><div class="workspace" :class="{collapsed}"><aside class="sidebar"><a href="#library" class="brand"><span class="brand-mark"><img src="/logo.png" alt="" width="32" height="32"/></span><span>video-rename</span></a><div class="sidebar-caption">工作空间</div><nav><button v-for="item in [{id:'library',name:'文件目录',icon:FolderOpen},{id:'history',name:'任务历史',icon:ScrollText},{id:'runs',name:'运行计划',icon:Clock3},{id:'settings',name:'系统设置',icon:Settings2}]" :key="item.id" :class="{active:page===item.id}" @click="emit('navigate',item.id)"><component :is="item.icon" :size="18"/><span>{{item.name}}</span><span v-if="page===item.id" class="nav-dot"/></button></nav><div class="sidebar-footer"><div class="model-box"><span class="eyebrow">视觉模型</span><strong :title="model">{{model||'未连接'}}</strong><span class="model-state"><i class="signal" :class="{off:!ready}"/>{{ready?'自动命名已就绪':'自动命名暂不可用'}}</span></div><div class="account"><div class="avatar">{{session?.username.slice(0,1).toUpperCase()}}</div><div><strong>{{session?.username}}</strong><small>管理员</small></div><button class="icon-btn" aria-label="退出登录" @click="logout"><LogOut :size="17"/></button></div><p v-if="error" class="error">{{error}}</p></div></aside><div class="workspace-main"><header class="topbar"><div><button class="icon-btn sidebar-toggle" aria-label="收起或展开导航" @click="collapsed=!collapsed"><PanelLeftClose :size="18"/></button><span>工作空间</span><span class="slash">/</span><strong>{{page==='library'?'文件目录':page==='history'?'任务历史':page==='settings'?'系统设置':'运行计划'}}</strong></div><span class="topbar-note"><span class="signal"/> 本地媒体库 <ArrowUpRight :size="14"/></span></header><main class="page-main"><slot/></main></div></div></template>
